//go:build windows

package main

import (
	_ "embed"
	"encoding/binary"
	"unsafe"

	"golang.org/x/sys/windows"
)

// Generated by tools/genicons (go run tools/genicons/main.go).
//
//go:embed assets/tray.ico
var trayICO []byte

//go:embed assets/odm.ico
var appICO []byte

func trayIcon() []byte { return trayICO }

// icoImage returns the PNG stored for the given size in an .ico made of PNG
// entries (as tools/genicons writes them), or nil.
func icoImage(ico []byte, size int) []byte {
	if len(ico) < 6 {
		return nil
	}
	n := int(binary.LittleEndian.Uint16(ico[4:]))
	for i := 0; i < n; i++ {
		e := ico[6+16*i:]
		if len(e) < 16 {
			return nil
		}
		w := int(e[0])
		if w == 0 {
			w = 256
		}
		ln, off := binary.LittleEndian.Uint32(e[8:]), binary.LittleEndian.Uint32(e[12:])
		if w == size && int(off+ln) <= len(ico) {
			return ico[off : off+ln]
		}
	}
	return nil
}

// setWindowIcon gives the frameless window the ODM icon in the taskbar and
// Alt+Tab (WebView2 windows otherwise show a generic one).
func setWindowIcon(hwnd uintptr, user32 *windows.LazyDLL) {
	create := user32.NewProc("CreateIconFromResourceEx")
	send := user32.NewProc("SendMessageW")
	const wmSetIcon, iconSmall, iconBig, lrDefaultColor = 0x0080, 0, 1, 0
	for _, it := range []struct {
		which uintptr
		size  int
	}{{iconSmall, 16}, {iconBig, 32}} {
		png := icoImage(appICO, it.size)
		if png == nil {
			continue
		}
		h, _, _ := create.Call(uintptr(unsafe.Pointer(&png[0])), uintptr(len(png)), 1, 0x00030000,
			uintptr(it.size), uintptr(it.size), lrDefaultColor)
		if h != 0 {
			send.Call(hwnd, wmSetIcon, it.which, h)
		}
	}
}
